function double(fn) {
  return function (...args) {
    return fn.apply(this, args) * 2;
  };
}

function plusOne(fn) {
  return function (...args) {
    return fn.apply(this, args) + 1;
  };
}

const shelf = {
  books: 5,
  count(extra) {
    return this.books + extra;
  },
};

shelf.first = plusOne(double(shelf.count));
shelf.second = double(plusOne(shelf.count));

console.log(shelf.count(1));
console.log(shelf.first(1));
console.log(shelf.second(1));
